<?php use Luna\Core\Csrf; use Luna\Core\View; $token = View::e(Csrf::token()); ?>
<section class="page-intro compact"><div><span class="eyebrow">Contabilità · incassi e pagamenti</span><h1>Tesoreria e partite</h1><p>Scadenzario clienti/fornitori, pagamenti, estratti conto e riconciliazione.</p></div><div class="inline-actions"><form method="post" action="/accounting/treasury/sync"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary" type="submit">Sincronizza documenti</button></form><a class="button ghost" href="/accounting/setup">Configurazione</a></div></section>
<?php $receivable = 0.0; $payable = 0.0; $overdue = 0; foreach ($openItems as $item) { if ($item['direction'] === 'RECEIVABLE') $receivable += (float) $item['outstanding']; else $payable += (float) $item['outstanding']; if ($item['status'] === 'OVERDUE') $overdue++; } ?>
<div class="accounting-kpis"><article><span>Crediti aperti</span><strong><?= View::money($receivable) ?></strong></article><article><span>Debiti aperti</span><strong><?= View::money($payable) ?></strong></article><article class="<?= $overdue ? 'attention' : '' ?>"><span>Partite scadute</span><strong><?= $overdue ?></strong></article><article><span>Movimenti da riconciliare</span><strong><?= count(array_filter($bankTransactions, static fn ($row) => $row['reconciliation_status'] !== 'MATCHED')) ?></strong></article></div>
<nav class="accounting-tabs"><a href="#open-items">Partite</a><a href="#payments">Pagamenti</a><a href="#banking">Banche</a><a href="#reconciliation">Riconciliazione</a><a href="#withholding">Ritenute</a></nav>

<section class="card" id="open-items"><div class="card-header"><div><span class="section-kicker">Scadenzario</span><h2>Partite aperte</h2></div><form method="get" class="inline-form"><label>Direzione <select name="direction"><option value="">Tutte</option><option value="RECEIVABLE" <?= $direction === 'RECEIVABLE' ? 'selected' : '' ?>>Crediti</option><option value="PAYABLE" <?= $direction === 'PAYABLE' ? 'selected' : '' ?>>Debiti</option></select></label><button class="button" type="submit">Filtra</button></form></div><div class="table-wrap"><table><thead><tr><th>Scadenza</th><th>Tipo</th><th>Controparte</th><th>Riferimento</th><th>Originario</th><th>Pagato</th><th>Residuo</th><th>Stato</th></tr></thead><tbody><?php foreach ($openItems as $item): ?><tr><td><?= View::date($item['due_date']) ?></td><td><?= $item['direction'] === 'RECEIVABLE' ? 'Credito' : 'Debito' ?></td><td class="primary-cell"><?= View::e($item['party_name']) ?></td><td><?= View::e($item['reference'] ?? '—') ?></td><td><?= View::money($item['original_amount']) ?></td><td><?= View::money($item['settled_amount']) ?></td><td class="primary-cell"><?= View::money($item['outstanding']) ?></td><td><span class="badge status-<?= strtolower((string) $item['status']) ?>"><?= View::e($item['status']) ?></span></td></tr><?php endforeach; ?><?php if (!$openItems): ?><tr><td colspan="8"><div class="table-empty"><strong>Nessuna partita aperta</strong><small>Sincronizza i documenti contabili.</small></div></td></tr><?php endif; ?></tbody></table></div></section>

<div class="content-grid" id="payments"><section class="card span-5"><div class="card-header"><div><span class="section-kicker">Operazione</span><h2>Registra incasso o pagamento</h2></div></div><form method="post" action="/accounting/treasury/payments" class="modern-form"><input type="hidden" name="_token" value="<?= $token ?>"><div class="form-grid single-card-form"><label class="field full-width"><span>Partita</span><select name="open_item_id" required><option value="">Seleziona…</option><?php foreach ($openItems as $item): ?><option value="<?= (int) $item['id'] ?>"><?= View::e(($item['direction'] === 'RECEIVABLE' ? 'INCASSO · ' : 'PAGAMENTO · ') . $item['party_name'] . ' · ' . $item['reference']) ?> · <?= View::money($item['outstanding']) ?></option><?php endforeach; ?></select></label><label class="field"><span>Data</span><input type="date" name="payment_date" value="<?= date('Y-m-d') ?>" required></label><label class="field"><span>Importo</span><input name="amount" inputmode="decimal" required></label><label class="field"><span>Metodo</span><select name="method"><option value="BANK_TRANSFER">Bonifico</option><option value="CASH">Contanti</option><option value="CARD">Carta</option><option value="DIRECT_DEBIT">Addebito</option><option value="OTHER">Altro</option></select></label><label class="field"><span>Conto bancario</span><select name="bank_account_id"><option value="">Cassa</option><?php foreach ($bankAccounts as $bank): if (empty($bank['active'])) continue; ?><option value="<?= (int) $bank['id'] ?>"><?= View::e($bank['name']) ?></option><?php endforeach; ?></select></label><label class="field full-width"><span>Riferimento</span><input name="reference_number"></label></div><div class="form-actions"><button class="button primary" type="submit">Contabilizza</button></div></form></section>
<section class="card data-card span-7"><div class="card-header"><div><span class="section-kicker">Storico</span><h2>Ultimi pagamenti</h2></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Tipo</th><th>Controparte</th><th>Importo</th><th>Banca</th><th>Riconciliato</th><th></th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?= View::date($payment['payment_date']) ?></td><td><?= View::e($payment['payment_type']) ?></td><td><?= View::e($payment['party_name'] ?? '—') ?></td><td><?= View::money($payment['amount']) ?></td><td><?= View::e($payment['bank_name'] ?? 'Cassa') ?></td><td><?= !empty($payment['reconciled']) ? 'Sì' : 'No' ?></td><td><?php if ($payment['status'] === 'POSTED'): ?><form method="post" action="/accounting/treasury/payments/<?= (int) $payment['id'] ?>/reverse" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input type="date" name="reversal_date" value="<?= date('Y-m-d') ?>"><button class="table-action danger-text" type="submit">Storna</button></form><?php else: ?><span class="badge status-reversed">STORNATO</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>

<div class="content-grid" id="banking"><section class="card span-5"><div class="card-header"><div><span class="section-kicker">Anagrafica</span><h2>Nuovo conto bancario</h2></div></div><form method="post" action="/accounting/treasury/bank-accounts" class="modern-form"><input type="hidden" name="_token" value="<?= $token ?>"><div class="form-grid single-card-form"><label class="field full-width"><span>Nome</span><input name="name" required></label><label class="field full-width"><span>IBAN</span><input name="iban" required></label><label class="field"><span>BIC</span><input name="bic"></label><label class="field"><span>Valuta</span><input name="currency" value="EUR" maxlength="3"></label><label class="field full-width"><span>Conto contabile</span><select name="chart_account_id"><option value="">Mappatura Banca</option><?php foreach ($accounts as $account): ?><option value="<?= (int) $account['id'] ?>"><?= View::e($account['code'] . ' · ' . $account['name']) ?></option><?php endforeach; ?></select></label><input type="hidden" name="active" value="1"></div><div class="form-actions"><button class="button primary" type="submit">Salva conto</button></div></form></section>
<section class="card span-7"><div class="card-header"><div><span class="section-kicker">Estratto conto</span><h2>Acquisisci movimento</h2></div></div><form method="post" action="/accounting/treasury/bank-transactions" class="modern-form"><input type="hidden" name="_token" value="<?= $token ?>"><div class="form-grid"><label class="field"><span>Conto</span><select name="bank_account_id" required><?php foreach ($bankAccounts as $bank): if (empty($bank['active'])) continue; ?><option value="<?= (int) $bank['id'] ?>"><?= View::e($bank['name']) ?></option><?php endforeach; ?></select></label><label class="field"><span>Data contabile</span><input type="date" name="booking_date" value="<?= date('Y-m-d') ?>" required></label><label class="field"><span>Data valuta</span><input type="date" name="value_date"></label><label class="field"><span>Importo con segno</span><input name="amount" inputmode="decimal" required><small>Positivo entrata, negativo uscita.</small></label><label class="field"><span>Controparte</span><input name="counterparty"></label><label class="field"><span>Riferimento</span><input name="reference"></label><label class="field full-width"><span>Descrizione</span><input name="description" required></label></div><div class="form-actions"><button class="button primary" type="submit">Acquisisci</button></div></form></section></div>

<section class="card" id="reconciliation"><div class="card-header"><div><span class="section-kicker">Abbinamento controllato</span><h2>Riconciliazione bancaria</h2></div></div><form method="post" action="/accounting/treasury/reconcile" class="modern-form"><input type="hidden" name="_token" value="<?= $token ?>"><div class="form-grid"><label class="field"><span>Movimento bancario</span><select name="transaction_id" required><option value="">Seleziona…</option><?php foreach ($bankTransactions as $row): if ($row['reconciliation_status'] === 'MATCHED') continue; ?><option value="<?= (int) $row['id'] ?>"><?= View::date($row['booking_date']) ?> · <?= View::e($row['account_name']) ?> · <?= View::money($row['amount']) ?> · <?= View::e($row['description']) ?></option><?php endforeach; ?></select></label><label class="field"><span>Pagamento</span><select name="payment_id" required><option value="">Seleziona…</option><?php foreach ($payments as $payment): if ($payment['status'] !== 'POSTED' || !empty($payment['reconciled'])) continue; ?><option value="<?= (int) $payment['id'] ?>"><?= View::date($payment['payment_date']) ?> · <?= View::e($payment['payment_type']) ?> · <?= View::money($payment['bank_amount'] ?: $payment['amount']) ?> · <?= View::e($payment['party_name'] ?? '') ?></option><?php endforeach; ?></select></label><label class="field"><span>Importo abbinato</span><input name="amount" inputmode="decimal" required></label></div><div class="form-actions"><button class="button primary" type="submit">Riconcilia</button></div></form><div class="table-wrap"><table><thead><tr><th>Data</th><th>Movimento</th><th>Pagamento</th><th>Importo</th><th></th></tr></thead><tbody><?php foreach ($links as $link): ?><tr><td><?= View::date($link['matched_at']) ?></td><td><?= View::e($link['transaction_description']) ?></td><td><?= View::date($link['payment_date']) ?> · <?= View::e($link['reference_number'] ?? '—') ?></td><td><?= View::money($link['matched_amount']) ?></td><td><form method="post" action="/accounting/treasury/reconciliations/<?= (int) $link['id'] ?>/delete"><input type="hidden" name="_token" value="<?= $token ?>"><button class="table-action danger-text" type="submit">Annulla</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>

<div class="content-grid" id="withholding"><section class="card span-5"><div class="card-header"><div><span class="section-kicker">Professionisti e agenti</span><h2>Registra ritenuta</h2></div></div><form method="post" action="/accounting/treasury/withholdings" class="modern-form"><input type="hidden" name="_token" value="<?= $token ?>"><div class="form-grid single-card-form"><label class="field full-width"><span>Partita fornitore</span><select name="open_item_id" required><option value="">Seleziona…</option><?php foreach ($openItems as $item): if ($item['direction'] !== 'PAYABLE') continue; ?><option value="<?= (int) $item['id'] ?>"><?= View::e($item['party_name'] . ' · ' . $item['reference']) ?> · <?= View::money($item['outstanding']) ?></option><?php endforeach; ?></select></label><label class="field"><span>Data pagamento</span><input type="date" name="record_date" value="<?= date('Y-m-d') ?>" required></label><label class="field"><span>Scadenza versamento</span><input type="date" name="due_date"></label><label class="field"><span>Tipo</span><select name="withholding_type"><option>IRPEF</option><option>INPS</option><option>ENASARCO</option><option>OTHER</option></select></label><label class="field"><span>Lordo chiuso</span><input name="gross_amount" inputmode="decimal" required></label><label class="field"><span>Imponibile %</span><input name="taxable_percent" value="100"></label><label class="field"><span>Aliquota %</span><input name="rate_percent" value="20"></label><label class="field"><span>Contributo trattenuto</span><input name="social_security_amount" value="0"></label><label class="field"><span>Conto bancario</span><select name="bank_account_id"><option value="">Cassa</option><?php foreach ($bankAccounts as $bank): ?><option value="<?= (int) $bank['id'] ?>"><?= View::e($bank['name']) ?></option><?php endforeach; ?></select></label></div><div class="form-actions"><button class="button primary" type="submit">Calcola e contabilizza</button></div></form></section>
<section class="card data-card span-7"><div class="card-header"><div><span class="section-kicker">Riepilogo</span><h2>Ritenute operate</h2></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Fornitore</th><th>Tipo</th><th>Lordo</th><th>Ritenuta</th><th>Netto</th><th>Stato</th><th></th></tr></thead><tbody><?php foreach ($withholdings as $row): ?><tr><td><?= View::date($row['record_date']) ?></td><td><?= View::e($row['supplier_name'] ?? '—') ?></td><td><?= View::e($row['withholding_type']) ?></td><td><?= View::money($row['gross_amount']) ?></td><td><?= View::money($row['withholding_amount']) ?></td><td><?= View::money($row['net_amount']) ?></td><td><span class="badge status-<?= strtolower((string) $row['status']) ?>"><?= View::e($row['status']) ?></span></td><td><?php if ($row['status'] === 'WITHHELD'): ?><form method="post" action="/accounting/treasury/withholdings/<?= (int) $row['id'] ?>/pay" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input type="date" name="payment_date" value="<?= date('Y-m-d') ?>"><select name="bank_account_id"><option value="">Cassa</option><?php foreach ($bankAccounts as $bank): ?><option value="<?= (int) $bank['id'] ?>"><?= View::e($bank['name']) ?></option><?php endforeach; ?></select><button class="table-action" type="submit">Versa</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
